div {
  width: 100px;
  height: 100px;
  background-color: #ff0000;
  border: 2px solid #000000;
}

.pixel-box {
  box-sizing: border-box;
  width: 100px;
  padding: 10px;
  border: 2px solid black;
  margin: 5px;
}

.container {
  position: relative;
}

.pixel-element {
  position: absolute;
  top: 20px;
  left: 30px;
}

@font-face {
  font-family: 'PixelFont';
  src: url('pixel-font.woff2');
}
.pixel-text {
  font-family: 'PixelFont', monospace;
  font-size: 16px;
}

.header {
  font-size: 24px;
}
.body-text {
  font-size: 16px;
}
.caption {
  font-size: 12px;
}

.pixel-icon {
  width: 32px;
  height: 32px;
  background-color: #3D5A80;
  border: 4px solid #E0FBFC;
}

.pixel-square {
  width: 16px;
  height: 16px;
  background-color: #98C1D9;
}

.pixel-circle {
  width: 16px;
  height: 16px;
  background-color: #98C1D9;
  border-radius: 0;
}

.pixel-heart {
  position: relative;
  width: 24px;
  height: 24px;
}

.pixel-heart::before,
.pixel-heart::after {
  content: '';
  position: absolute;
  width: 12px;
  height: 12px;
  background-color: #E040FB;
}

.pixel-head {
  width: 32px;
  height: 32px;
  background-color: #FAD7A0;
  border: 2px solid #3D5A80;
}

.pixel-body {
  width: 24px;
  height: 32px;
  background-color: #98C1D9;
  margin-top: -2px;
}

.pixel-leg {
  width: 8px;
  height: 16px;
  background-color: #3D5A80;
  position: absolute;
}

.pixel-tree {
  width: 32px;
  height: 48px;
  position: relative;
}

.pixel-tree::before {
  content: '';
  position: absolute;
  width: 24px;
  height: 24px;
  background-color: #98C1D9;
  top: 0;
  left: 4px;
}

.pixel-eye {
  width: 8px;
  height: 8px;
  background-color: #000;
  animation: blink 3s infinite;
}
@keyframes blink {
  0%, 90%, 100% { height: 8px; }
  95% { height: 2px; }
}

.pixel-character {
  position: relative;
  animation: walk 2s infinite;
}
@keyframes walk {
  0% { transform: translateX(0); }
  50% { transform: translateX(20px); }
  100% { transform: translateX(0); }
}

/* 简单呼吸效果 */
.pixel-heart {
  animation: breathe 1.5s infinite;
}
@keyframes breathe {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.1); }
}

/* 跳跃动画 */
.pixel-character {
  animation: jump 1s infinite;
}
@keyframes jump {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-20px); }
}

.pixel-btn {
  width: 80px;
  height: 32px;
  background-color: #FF6B6B;
  border: 2px solid #000;
  cursor: pointer;
}

.pixel-btn:hover {
  background-color: #FF8E8E;
  transform: translateY(-2px);
  box-shadow: 0 2px 0 #000;
}

.pixel-link {
  color: #4ECDC4;
  text-decoration: none;
  position: relative;
}
.pixel-link:hover::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  width: 100%;
  height: 2px;
  background-color: #4ECDC4;
}

.pixel-input {
  width: 200px;
  height: 32px;
  border: 2px solid #000;
  background-color: #F8F8F8;
  padding: 0 4px;
}

.pixel-input {
  width: 200px;
  height: 32px;
  border: 2px solid #000;
  background-color: #F8F8F8;
  padding: 0 4px;
  font-family: monospace;
  font-size: 14px;
}

.pixel-input:focus {
  outline: none;
  border-color: #4ECDC4;
  background-color: #FFFFFF;
  box-shadow: 0 0 0 2px #4ECDC4;
}

.pixel-input:hover {
  border-color: #4ECDC4;
}

.pixel-input:disabled {
  background-color: #E0E0E0;
  cursor: not-allowed;
}

.nav-menu {
  display: flex;
  list-style: none;
  padding: 0;
  margin: 0;
  background-color: #F8F8F8;
  border: 2px solid #000;
}

.pixel-nav ul {
  display: flex;
  border: 2px solid #000;
}

.pixel-nav li {
  border-right: 2px solid #000;
}

.pixel-nav a {
  display: block;
  padding: 8px 16px;
  color: #000;
  text-decoration: none;
}

.pixel-nav a:hover {
  background-color: #FFF;
  border-color: #4ECDC4;
}

.pixel-nav a.active {
  background-color: #4ECDC4;
  color: #FFF;
}

@media (max-width: 768px) {
  .nav-menu {
    flex-direction: column;
  }
}

.nav-menu {
  display: flex;
  flex-wrap: wrap;
}

@media (max-width: 768px) {
  .nav-menu {
    flex-direction: column;
  }
  .nav-menu li {
    width: 100%;
    border-bottom: 2px solid #000;
  }
}

img {
  image-rendering: pixelated;
  image-rendering: -moz-crisp-edges;
  image-rendering: crisp-edges;
}

/* 优化前 */
.pixel-container {
  background: #ffffff;
  padding: 10px;
  margin: 5px;
}

/* 优化后 */
.pixel-container {
  background: #fff;
  padding: 10px;
  margin: 5px;
}

/* 使用简写属性 */
.pixel-box {
  margin: 5px 10px;
}

/* 移除重复样式 */
.pixel-box {
  background: #fff;
}

/* 使用CSS变量 */
:root {
  --pixel-size: 10px;
}

// 优化前
function updatePixelArt() {
  const elements = document.querySelectorAll('.pixel');
  elements.forEach(el => {
    el.style.background = '#fff';
  });
}

// 优化后
function updatePixelArt() {
  requestAnimationFrame(() => {
    const elements = document.querySelectorAll('.pixel');
    elements.forEach(el => {
      el.style.background = '#fff';
    });
  });

