function shouldLoadImage(imageTop, viewportTop, viewportHeight) {
  const imageBottom = imageTop + 100;
  const viewportBottom = viewportTop + viewportHeight;
  if (imageTop >= viewportBottom || imageBottom <= viewportTop) return false;
  return true;
}
